// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero and amount in a reasonable range (but allow wide range)
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1e18); // at least 1 wei, up to 1 ETH for practicality

        // Fund depositor so they can deposit
        vm.deal(depositor, amount);
        // depositor makes a deposit
        vm.prank(depositor);
        c.deposit{value: amount}();

        // record stored credit before withdraw (use the public getter credit via storage: credit is private in source, but assume C provides no getter for credit; however problem statement says difference observable via public surface: use address(c).balance and try-withdraw to observe success and then call withdraw again to see behavior)
        // The reference guarantees that after withdrawAll the depositor's credit is zero; since credit mapping is private in original contract, we instead test by: after first withdrawAll, a second withdrawAll should revert or return ok=false because oCredit==0 and no funds are sent (but both versions will succeed); instead we observe that address(c).balance decreases by amount and remains decreased and that a subsequent deposit+withdraw behaves same. To directly observe stored credit we rely on behaviour: after withdrawAll, sending withdrawAll again should not transfer funds. We detect transfer by checking depositor balance change.

        // capture initial balances
        uint256 beforeDepositorBal = depositor.balance;
        uint256 beforeContractBal = address(c).balance;

        // perform withdrawAll: should succeed and transfer 'amount' to depositor
        vm.prank(depositor);
        bool ok1;
        try c.withdrawAll() {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        // withdrawAll should succeed for the reference (no revert), so ok1 must be true for all inputs
        assertTrue(ok1);

        // balances after first withdraw
        uint256 afterDepositorBal = depositor.balance;
        uint256 afterContractBal = address(c).balance;

        // depositor should have received amount (or at least contract balance decreased by amount)
        // check contract balance decreased by exactly amount
        assertTrue(afterContractBal + amount == beforeContractBal);

        // Now call withdrawAll again; in the correct contract there's no remaining credit, so second withdraw transfers nothing.
        // We'll detect that by checking contract balance does not decrease further and that the call succeeds.
        vm.prank(depositor);
        bool ok2;
        try c.withdrawAll() {
            ok2 = true;
        } catch {
            ok2 = false;
        }
        // second call should also succeed (no revert) on reference
        assertTrue(ok2);

        uint256 finalContractBal = address(c).balance;

        // FINAL ASSERTION: after the first successful withdrawAll, the contract's balance remains unchanged by a second withdrawAll
        // (i.e., stored credit for depositor was cleared). This is the single assertTrue required to capture the universal property.
        assertTrue(finalContractBal == afterContractBal);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: depositor address and deposit amount
    function testFuzz_property(address actor, uint256 amount) public {
        // keep actor non-zero and amount in a reasonable range (but wide)
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);

        // give the actor some ether and perform deposit
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // call withdrawAll as the actor
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: after a successful withdrawAll the stored credit for the caller is zero.
        // Read the auto-generated getter credit(actor) via a call to the contract's public mapping getter.
        // Since credit is declared in the original contract as `mapping(address => uint) credit;` (not public),
        // there is no auto getter. However the behavior can be observed via attempting to withdraw again:
        // if withdrawAll succeeded and credit was cleared, a subsequent withdrawAll should do nothing
        // (succeed and not send funds). We observe this by calling withdrawAll again and expecting it to succeed
        // (ok2 == true) and not change contract balance. To adhere to the requirement of a single assertTrue
        // that reads c's public surface, we use address(c).balance equivalence after the second withdraw.

        // Record contract balance before second withdraw
        uint256 balBefore = address(c).balance;

        vm.prank(actor);
        bool ok2;
        try c.withdrawAll() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        uint256 balAfter = address(c).balance;

        // For the correct contract: if the first withdraw succeeded (ok==true), then the stored credit was cleared,
        // so the second withdraw should also succeed and not change the contract balance (no further funds withdrawn).
        // The mutant leaves credit = oCredit*2 after the first withdraw, so for some inputs the second withdraw will
        // succeed and withdraw again, changing address(c).balance and violating this property.
        assertTrue(!(ok == true) || (ok2 == true && balAfter == balBefore));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: actor who deposits/withdraws and deposit amount
    function testFuzz_property(address actor, uint128 amount) public {
        // keep actor non-zero and amount in a practical range
        vm.assume(actor != address(0));
        uint128 amt = amount % 1 ether; // bound to reasonable gas/eth size
        vm.assume(amt > 0);

        // fund the actor so they can deposit
        vm.deal(actor, amt);

        // actor deposits amt
        vm.prank(actor);
        c.deposit{value: amt}();

        // first withdrawAll should succeed (and transfer funds out)
        bool ok1;
        vm.prank(actor);
        try c.withdrawAll() {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        // after successful first withdraw, the contract's lock should be cleared
        // We observe this by attempting a second withdrawAll: with correct contract it will simply be callable (it may do nothing but must not be blocked by the lock).
        bool ok2;
        vm.prank(actor);
        try c.withdrawAll() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // General property: if the first withdraw call succeeded, the second withdraw call must also be callable (lock released).
        assertTrue(!(ok1 == true && ok2 == false));
    }
}
